1	<title>Portal Redesign — Deploy Wizard</title>
2	<link rel="preconnect" href="https://fonts.googleapis.com">
3	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
4	<link href="https://fonts.googleapis.com/css2?family=Sora:wght@500;600;700;800&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
5	
6	<style>
7	  :root{
8	    --bg:#05060d; --surface-1:#0c0f1c; --border:rgba(255,255,255,0.07); --border-strong:rgba(255,255,255,0.16);
9	    --text:#f4f5fb; --text-muted:#97a1c4; --text-faint:#5b6488;
10	    --brand:#6f47f5; --brand-light:#a48bff; --cyan:#22d3ee; --blue:#3b82f6; --good:#34d399;
11	    --font-display:"Sora","Inter",system-ui,sans-serif; --font-body:"Inter",system-ui,sans-serif;
12	  }
13	  *{ box-sizing:border-box; }
14	  body{ margin:0; background:var(--bg); color:var(--text); font-family:var(--font-body); -webkit-font-smoothing:antialiased; padding:32px 24px 64px; }
15	  .wrap{ max-width:1160px; margin:0 auto; }
16	  .tag{ display:flex; align-items:center; gap:8px; font-size:11px; font-weight:700; letter-spacing:.06em; text-transform:uppercase; color:var(--text-faint); margin-bottom:18px; }
17	  .tag .dot{ width:6px; height:6px; border-radius:999px; background:var(--brand-light); box-shadow:0 0 0 3px rgba(164,139,255,0.18); }
18	
19	  .stepper{ display:flex; align-items:center; gap:10px; margin-bottom:28px; flex-wrap:wrap; }
20	  .step{ display:flex; align-items:center; gap:9px; }
21	  .step .chip{ width:26px; height:26px; border-radius:999px; display:flex; align-items:center; justify-content:center; font-size:11.5px; font-weight:700; border:1px solid var(--border-strong); color:var(--text-faint); }
22	  .step.done .chip{ background:rgba(52,211,153,0.16); border-color:rgba(52,211,153,0.4); color:#6ee7b3; }
23	  .step.current .chip{ background:rgba(111,71,245,0.2); border-color:var(--brand-light); color:var(--brand-light); box-shadow:0 0 0 4px rgba(111,71,245,0.12); }
24	  .step .label{ font-size:13px; color:var(--text-faint); font-weight:600; }
25	  .step.current .label{ color:var(--text); }
26	  .step-line{ width:30px; height:1px; background:var(--border-strong); }
27	
28	  .layout{ display:grid; grid-template-columns:1fr 340px; gap:24px; align-items:start; }
29	  @media (max-width:900px){ .layout{ grid-template-columns:1fr; } }
30	
31	  h1{ font-family:var(--font-display); font-size:24px; font-weight:700; margin:0 0 6px; }
32	  .sub{ color:var(--text-muted); font-size:13.5px; margin:0 0 24px; }
33	
34	  .panel{ background:var(--surface-1); border:1px solid var(--border); border-radius:20px; padding:24px; margin-bottom:16px; }
35	  .panel-title{ font-family:var(--font-display); font-size:14.5px; font-weight:700; margin-bottom:3px; }
36	  .panel-sub{ font-size:12px; color:var(--text-faint); margin-bottom:16px; }
37	
38	  /* plan comparison */
39	  .plans{ display:grid; grid-template-columns:repeat(4,1fr); gap:12px; }
40	  @media (max-width:760px){ .plans{ grid-template-columns:repeat(2,1fr); } }
41	  .plan{ position:relative; border:1px solid var(--border); border-radius:16px; padding:16px 14px; cursor:pointer; transition:border-color .15s ease, transform .15s ease; }
42	  .plan:hover{ border-color:var(--border-strong); transform:translateY(-2px); }
43	  .plan.selected{ border-color:var(--brand-light); background:linear-gradient(160deg,rgba(111,71,245,0.14),rgba(12,15,28,0.4)); box-shadow:0 0 0 1px var(--brand-light), 0 16px 32px -18px rgba(111,71,245,0.6); }
44	  .plan.selected::after{ content:"✓"; position:absolute; top:10px; right:10px; width:18px; height:18px; border-radius:999px; background:var(--brand); color:#0a0714; font-size:10px; font-weight:800; display:flex; align-items:center; justify-content:center; }
45	  .plan .badge{ position:absolute; top:-9px; left:14px; background:var(--brand); color:#fff; font-size:9.5px; font-weight:700; padding:3px 8px; border-radius:999px; }
46	  .plan-glyph{ width:100%; height:52px; margin-bottom:10px; }
47	  .plan-name{ font-weight:700; font-size:13.5px; margin-bottom:6px; }
48	  .plan-price{ font-family:var(--font-display); font-size:19px; font-weight:800; margin-bottom:8px; }
49	  .plan-price span{ font-family:var(--font-body); font-size:11px; font-weight:500; color:var(--text-faint); }
50	  .plan-specs{ font-size:11px; color:var(--text-muted); line-height:1.7; }
51	
52	  .term-row{ display:flex; gap:8px; margin-top:16px; }
53	  .term{ flex:1; text-align:center; padding:8px 6px; border-radius:10px; border:1px solid var(--border); font-size:12px; font-weight:600; color:var(--text-muted); cursor:pointer; }
54	  .term.active{ border-color:var(--brand-light); color:var(--text); background:rgba(111,71,245,0.1); }
55	  .term small{ display:block; color:var(--good); font-weight:700; font-size:10px; margin-top:2px; }
56	
57	  .expand-row{ display:flex; align-items:center; justify-content:space-between; cursor:pointer; padding:14px 0; border-top:1px solid var(--border); }
58	  .expand-row:first-child{ border-top:none; padding-top:0; }
59	  .expand-left{ display:flex; align-items:center; gap:11px; }
60	  .expand-icon{ width:34px; height:34px; border-radius:10px; background:rgba(255,255,255,0.04); border:1px solid var(--border); display:flex; align-items:center; justify-content:center; flex-shrink:0; }
61	  .expand-icon svg{ width:16px; height:16px; color:var(--brand-light); }
62	  .expand-title{ font-size:13.5px; font-weight:600; }
63	  .expand-current{ font-size:11.5px; color:var(--text-faint); }
64	  .expand-chev{ width:15px; height:15px; color:var(--text-faint); transition:transform .2s ease; }
65	  .expand-row.open .expand-chev{ transform:rotate(180deg); }
66	  .expand-body{ display:none; padding:0 0 16px 45px; }
67	  .expand-row.open + .expand-body{ display:block; }
68	  .os-grid{ display:grid; grid-template-columns:repeat(3,1fr); gap:8px; }
69	  .os-opt{ display:flex; align-items:center; gap:8px; padding:9px 11px; border:1px solid var(--border); border-radius:10px; font-size:12px; cursor:pointer; }
70	  .os-opt.sel{ border-color:var(--brand-light); background:rgba(111,71,245,0.08); }
71	
72	  /* trust strip */
73	  .trust{ display:flex; gap:18px; flex-wrap:wrap; margin:6px 0 0; padding-top:16px; border-top:1px solid var(--border); }
74	  .trust-item{ display:flex; align-items:center; gap:7px; font-size:12px; color:var(--text-muted); }
75	  .trust-item svg{ width:15px; height:15px; color:var(--good); flex-shrink:0; }
76	
77	  /* summary sidebar */
78	  .summary{ background:var(--surface-1); border:1px solid var(--border); border-radius:20px; padding:22px; position:sticky; top:24px; }
79	  .summary-title{ font-family:var(--font-display); font-size:13.5px; font-weight:700; margin-bottom:14px; }
80	  .sum-row{ display:flex; justify-content:space-between; font-size:12.5px; padding:8px 0; border-bottom:1px solid var(--border); color:var(--text-muted); }
81	  .sum-row span:last-child{ color:var(--text); font-weight:600; }
82	  .sum-total{ display:flex; justify-content:space-between; align-items:baseline; padding:16px 0 4px; }
83	  .sum-total .lbl{ font-size:13px; color:var(--text-muted); }
84	  .sum-total .val{ font-family:var(--font-display); font-size:26px; font-weight:800; }
85	  .sum-total .val small{ font-family:var(--font-body); font-size:12px; font-weight:500; color:var(--text-faint); }
86	  .continue-btn{ width:100%; margin-top:14px; background:linear-gradient(135deg,var(--brand-light),var(--brand)); color:#0a0714; font-weight:700; font-size:14px; border:none; border-radius:13px; padding:14px; cursor:pointer; display:flex; align-items:center; justify-content:center; gap:8px; }
87	  .continue-btn svg{ width:15px; height:15px; }
88	  .guarantee{ margin-top:12px; font-size:11px; color:var(--text-faint); text-align:center; }
89	
90	  @media (prefers-reduced-motion: reduce){ .plan{ transition:none; } }
91	</style>
