93	<div class="wrap">
94	  <div class="tag"><span class="dot"></span>Concept mockup — new deploy flow, not wired to checkout</div>
95	
96	  <div class="stepper">
97	    <div class="step current"><span class="chip">1</span><span class="label">Plan</span></div>
98	    <span class="step-line"></span>
99	    <div class="step"><span class="chip">2</span><span class="label">Review & pay</span></div>
