126	            <svg class="plan-glyph" viewBox="0 0 120 52" fill="none"><rect x="18" y="10" width="84" height="10" rx="2.5" stroke="#a48bff" stroke-width="1.8"/><rect x="18" y="24" width="84" height="10" rx="2.5" stroke="#a48bff" stroke-width="1.8"/><rect x="18" y="38" width="84" height="8" rx="2.5" stroke="#a48bff" stroke-width="1.8" opacity=".5"/><circle cx="27" cy="15" r="1.5" fill="#a48bff"/><circle cx="27" cy="29" r="1.5" fill="#a48bff"/><circle cx="36" cy="15" r="1.5" fill="#a48bff"/><circle cx="36" cy="29" r="1.5" fill="#a48bff"/><circle cx="45" cy="15" r="1.5" fill="#a48bff"/></svg>
127	            <div class="plan-name">Pro</div>
128	            <div class="plan-price">$20.99<span>/mo</span></div>
129	            <div class="plan-specs">3 vCPU · 8 GB RAM<br>80 GB NVMe · 4 TB</div>
130	          </div>
131	          <div class="plan" data-plan="max">
132	            <svg class="plan-glyph" viewBox="0 0 120 52" fill="none"><rect x="14" y="8" width="92" height="9" rx="2.5" stroke="#5b6488" stroke-width="1.6"/><rect x="14" y="21" width="92" height="9" rx="2.5" stroke="#5b6488" stroke-width="1.6"/><rect x="14" y="34" width="92" height="9" rx="2.5" stroke="#5b6488" stroke-width="1.6"/></svg>
133	            <div class="plan-name">Max</div>
134	            <div class="plan-price">$32.99<span>/mo</span></div>
135	            <div class="plan-specs">4 vCPU · 16 GB RAM<br>120 GB NVMe · 8 TB</div>
136	          </div>
137	        </div>
138	
139	        <div class="term-row">
140	          <div class="term" data-term="monthly">Monthly</div>
141	          <div class="term active" data-term="annual">Annual<small>Save 20%</small></div>
142	          <div class="term" data-term="biennial">2 years<small>Save 30%</small></div>
143	          <div class="term" data-term="triennial">3 years<small>Save 40%</small></div>
144	        </div>
145	      </div>
146	
147	      <div class="panel">
148	        <div class="panel-title">Everything else, already set</div>
149	        <div class="panel-sub">Expand only what you want to change — the rest deploys with these defaults.</div>
150	
151	        <div class="expand-row" data-expand="os">
152	          <div class="expand-left">
153	            <div class="expand-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="14" rx="2"/><path d="M8 21h8M12 18v3"/></svg></div>
154	            <div><div class="expand-title">Operating system</div><div class="expand-current">Ubuntu 24.04 LTS</div></div>
155	          </div>
