157	        </div>
158	        <div class="expand-body">
159	          <div class="os-grid">
160	            <div class="os-opt sel">Ubuntu 24.04</div>
161	            <div class="os-opt">Debian 12</div>
162	            <div class="os-opt">AlmaLinux 9</div>
