167	        </div>
168	
169	        <div class="expand-row" data-expand="addons">
170	          <div class="expand-left">
171	            <div class="expand-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3 5 6v5.5c0 4.4 3 7.7 7 9 4-1.3 7-4.6 7-9V6l-7-3Z"/></svg></div>
172	            <div><div class="expand-title">Add-ons</div><div class="expand-current">Malware scanner + daily backups (free), Docker manager (free)</div></div>
173	          </div>
174	          <svg class="expand-chev" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg>
175	        </div>
176	        <div class="expand-body"><div class="os-grid"><div class="os-opt sel">Malware scanner</div><div class="os-opt sel">Daily backups</div><div class="os-opt sel">Docker manager</div></div></div>
177	
178	        <div class="expand-row" data-expand="access">
179	          <div class="expand-left">
180	            <div class="expand-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="10" width="16" height="10" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg></div>
