182	          </div>
183	          <svg class="expand-chev" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m6 9 6 6 6-6"/></svg>
184	        </div>
185	        <div class="expand-body"><input type="text" value="ubuntu-0mty" style="width:100%;background:rgba(255,255,255,0.04);border:1px solid var(--border);border-radius:9px;padding:9px 12px;color:var(--text);font-size:13px"></div>
186	
187	        <div class="trust">
188	          <div class="trust-item"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m5 13 4 4L19 7"/></svg>99.9% uptime SLA</div>
189	          <div class="trust-item"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m5 13 4 4L19 7"/></svg>24/7 expert support</div>
190	          <div class="trust-item"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m5 13 4 4L19 7"/></svg>Instant setup</div>
191	        </div>
192	      </div>
193	    </div>
194	
195	    <div class="summary">
196	      <div class="summary-title">Order summary</div>
197	      <div class="sum-row"><span>Plan</span><span id="sumPlan">Pro — 3 vCPU / 8GB</span></div>
198	      <div class="sum-row"><span>OS</span><span>Ubuntu 24.04</span></div>
199	      <div class="sum-row"><span>Billing term</span><span id="sumTerm">Annual (-20%)</span></div>
200	      <div class="sum-total">
201	        <span class="lbl">Total due today</span>
202	        <span class="val" id="sumPrice">$7.10<small>/mo</small></span>
203	      </div>
204	      <button class="continue-btn">Continue to payment
205	        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 5l7 7-7 7"/></svg>
206	      </button>
207	      <div class="guarantee">Secured checkout · cancel anytime</div>
208	    </div>
209	  </div>
210	</div>
