212	<script>
213	  const PRICES = { starter: 8.88, standard: 12.99, pro: 20.99, max: 32.99 };
214	  const NAMES = { starter: 'Starter — 1 vCPU / 2GB', standard: 'Standard — 2 vCPU / 4GB', pro: 'Pro — 3 vCPU / 8GB', max: 'Max — 4 vCPU / 16GB' };
215	  const TERM_MULT = { monthly: 1, annual: .8, biennial: .7, triennial: .6 };
216	  const TERM_LABEL = { monthly: 'Monthly', annual: 'Annual (-20%)', biennial: 'Biennial (-30%)', triennial: 'Triennial (-40%)' };
217	  let plan = 'pro', term = 'annual';
218	
219	  function render(){
220	    document.getElementById('sumPlan').textContent = NAMES[plan];
221	    document.getElementById('sumTerm').textContent = TERM_LABEL[term];
222	    document.getElementById('sumPrice').innerHTML = '$' + (PRICES[plan] * TERM_MULT[term]).toFixed(2) + '<small>/mo</small>';
223	  }
224	
225	  document.querySelectorAll('.plan').forEach(el => {
226	    el.addEventListener('click', () => {
227	      document.querySelectorAll('.plan').forEach(p => p.classList.remove('selected'));
228	      el.classList.add('selected');
229	      plan = el.dataset.plan;
230	      render();
231	    });
232	  });
233	  document.querySelectorAll('.term').forEach(el => {
234	    el.addEventListener('click', () => {
235	      document.querySelectorAll('.term').forEach(t => t.classList.remove('active'));
236	      el.classList.add('active');
237	      term = el.dataset.term;
238	      render();
239	    });
240	  });
241	  document.querySelectorAll('.expand-row').forEach(el => {
242	    el.addEventListener('click', () => el.classList.toggle('open'));
243	  });
244	  render();
245	</script>
