41	type Plan = {
42	  id: string; name: string; cpuCores: number; ramMB: number; diskGB: number;
43	  bandwidthTB: number; priceCents: number; storageTier: string;
44	};
45	type Image = {
46	  id: string; slug: string; name: string; category: string; family: string;
47	  version: string; logo: string; minRamMB: number; minDiskGB: number;
48	  licenseRequired: boolean; featured: boolean;
49	};
50	type NodeOpt = { id: string; name: string; publicIp: string };
51	
