338	  // discriminated union — {type:"loading"} while the Elements SDK is still
339	  // initializing, {type:"error"} if it failed, {type:"success", checkout}
340	  // once ready. `checkoutActions` is that inner `checkout` object, undefined
341	  // until "success" — every confirm() call below is guarded on it existing,
342	  // so a click during the loading window can't throw.
343	  const checkoutState = useCheckoutElements();
344	  const checkoutActions = checkoutState.type === "success" ? checkoutState.checkout : undefined;
