/* ── Deploy-wizard plan-tier "rack" glyphs ──────────────────────────────── */

/**
 * The small illustration on each VPS plan card in the redesigned deploy
 * wizard (scratchpad/portal-redesign-wizard.html's `.plan-glyph`) — a bank of
 * server-rack bars that visibly gets denser from Starter to Max. Deliberately
 * NOT the 24×24 nav-icon shape above: the mockup draws these on a wide
 * 120×52 canvas (a card illustration, not a nav glyph), the same kind of
 * documented exception `<Gauge>` in primitives.tsx already makes for its own
 * non-square viewBox. `currentColor` throughout (the mockup hardcoded a
 * distinct hex per tier — #5b6488/#97a1c4/#a48bff/#5b6488 — which this
 * reproduces via the call site's `text-*` class instead, matching every
 * other icon in this file's color convention) so a selected card can simply
 * switch to `text-pv-brand-light` rather than needing 4 more hardcoded
 * variants.
 */
function makeRackGlyph(displayName: string, body: React.ReactNode) {
  function RackCmp({ className, ...props }: IconProps) {
    return (
      <svg viewBox="0 0 120 52" fill="none" className={className} {...props}>
        {body}
      </svg>
    );
  }
  RackCmp.displayName = displayName;
  return RackCmp;
}

