);

const RACK_GLYPHS = [IconRackStarter, IconRackStandard, IconRackPro, IconRackMax] as const;

/**
 * Resolve a plan's position in the catalogue's sort order (0-based) to one of
 * the 4 approved rack glyphs above. The real plan catalogue is admin-managed
 * (any count, any names), so this scales by INDEX rather than by name —
 * anything past the 4th tier reuses the Max pattern rather than inventing a
 * 5th one that was never approved in the mockup.
 */
export function planRackGlyph(tierIndex: number) {
  return RACK_GLYPHS[Math.min(Math.max(tierIndex, 0), RACK_GLYPHS.length - 1)];
}

