  current,
  expanded,
  onToggle,
  rowRef,
  children,
}: {
  icon: React.ReactNode;
  title: string;
  current: React.ReactNode;
  expanded: boolean;
  onToggle: () => void;
  /** Scroll target for `goToSection` — attached to the row's own wrapper so
