const multiNode = nodes.length > 1;
// The redesigned wizard collapses what used to be 5 real steps (Plan,
// Location, Install, Add-ons, Access) plus Review into 2: Plan (which now
// ALSO contains Location/Install/Add-ons/Access as expandable-with-defaults
// sections — see `ExpandRow` above) and Review & Pay. Every control from
// every old step still renders somewhere below; only the step boundary and
// the container around it changed. `WIZARD_STEPS` feeds the new <Stepper>
// and the deploy-funnel tracking calls — the funnel now records arrivals at
// 2 milestones instead of up to 6, which is an intentional consequence of
// the redesign (a reviewer comparing funnel dashboards before/after should
// expect coarser step granularity, not a bug).
const WIZARD_STEPS = ["Plan", "Review & Pay"];
const [step, setStep] = useState(0);
// Which of the "Everything else, already set" sections is currently open.
// Defaults are pre-validated (see the hostname/image effects below), so
// null (everything collapsed) is the common case — nothing here changes
// what those defaults ARE, only how they're first presented.
const [expandedSection, setExpandedSection] = useState<"location" | "install" | "addons" | "access" | null>(null);
// Scroll targets for the Plan-step panels/rows, so a "Change" link clicked
// from the Review step can bring the customer back to the exact section
// they need — never to a blank, unscrolled top of Step 1. See `goToSection`.
const sectionRefs = useRef<Partial<Record<"plan" | "location" | "install" | "addons" | "access", HTMLDivElement | null>>>({});
const pendingScrollRef = useRef<"plan" | "location" | "install" | "addons" | "access" | null>(null);
/**
 * The ONLY way anything on the Review step sends the customer back to
 * Step 1. Real incident this replaces: the old 6-step wizard's "Change"
 * links called a bare `setStep(0)`, which — in THAT design — really did
 * land on a mostly-blank Plan screen, since Plan/Location/Install/Add-ons/
 * Access were each their own step and the customer's later choices weren't
 * visible from Plan. Now Step 1 contains everything at once (plan cards
 * already show the selection, sections already reflect current values), so
 * `setStep(0)` alone is no longer "blank" — but this still expands the
 * specific section being changed (if any) and scrolls it into view, so the
 * customer never has to go hunting for what they clicked "Change" on.
 */
const goToSection = useCallback((section: "plan" | "location" | "install" | "addons" | "access") => {
  if (section !== "plan") setExpandedSection(section);
  pendingScrollRef.current = section;
  setStep(0);
}, []);
useEffect(() => {
  if (step !== 0 || !pendingScrollRef.current) return;
  const target = pendingScrollRef.current;
  pendingScrollRef.current = null;
  const raf = requestAnimationFrame(() => {
    sectionRefs.current[target]?.scrollIntoView({ behavior: "smooth", block: "start" });
  });
  return () => cancelAnimationFrame(raf);
}, [step]);

// Deploy-funnel: record reaching each wizard step (de-duped per session in the
// helper) so the admin funnel shows how far people get. Delayed a few seconds
// rather than firing on mount — an instant bounce (e.g. a curious click on the
// generic "Deploy" nav link, which lands here by default with no ?product=)
// was inflating the Plan-step numerator with visits that never actually looked
// at pricing. Cleared if the step changes again or the wizard unmounts before
// the delay elapses, so only a genuine few-second view counts.
useEffect(() => {
  const t = window.setTimeout(() => {
    trackDeployStep("vps", WIZARD_STEPS[step] ?? String(step), step);
  }, 3000);
  return () => window.clearTimeout(t);
  // WIZARD_STEPS content is stable; fire on step change only.
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [step]);

// Deploy-funnel: when payAndDeploy returns an error, record it against the
// current step so a BUG/provision failure is distinguishable from abandonment.
useEffect(() => {
  if (state?.error) trackDeployError("vps", WIZARD_STEPS[step] ?? "Review & Pay", step, "ORDER_ERROR", state.error);
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [state?.error]);

